'use client'
/** Keypad: the MATRIX card `ui-keypad` (interactive: pointer and keyboard edit its data). Generated by scripts/registry/generate.ts. */
import { MatrixDotCard, type MatrixDotCardProps } from '@/components/matrix/dot-card'
import { componentsBoard } from '@/lib/matrix/widgets/boards/components'

const preset = componentsBoard.find(p => p.id === 'ui-keypad')!

export type MatrixKeypadProps = Omit<MatrixDotCardProps, 'preset'>

export function MatrixKeypad(props: MatrixKeypadProps) {
  return <MatrixDotCard preset={preset} {...props} />
}
